insert into public.spark_subjects (id,name,short_name,qualification,mark,description,enabled,status,sort_order,implementation,study_view,capabilities,routes,stats,learning_config,manifest_version) values ('principles-of-accounts','CSEC Principles of Accounts','Principles of Accounts','CSEC','PA','Clear accounting notes, original practice, source papers and a connected accounting workspace.',false,'draft',49,'generic','study','{"study":true,"practice":true,"flashcards":true,"progress":true,"paper1":true,"paper2":true,"adaptive":false,"structured":true,"labs":true,"sba":true}'::jsonb,'{"study":"/study/principles-of-accounts","practice":"/practice/principles-of-accounts","flashcards":"/dashboard/flashcards/principles-of-accounts","progress":"/dashboard/progress"}'::jsonb,'{"sections":11,"topics":33,"objectives":106,"flashcards":66,"paper1OriginalQuestions":60,"paper2OriginalPapers":1,"historicalFiles":51,"distinctHistoricalPdfs":50,"verifiedHistoricalKeys":0}'::jsonb,'{"syllabusCode":"CXC 10/G/SYLL 17","syllabusUrl":"https://www.cxc.org/wp-content/uploads/2018/11/CSEC-Principles-of-Accounts-Syllabus.pdf","exam":{"paper1":{"questions":60,"marks":60,"durationMinutes":90},"paper2":{"questions":5,"marks":100,"marksPerQuestion":20,"durationMinutes":180,"compulsory":true},"sba":{"marks":40},"alternative":{"marks":40,"durationMinutes":90}},"releaseStage":"course-review-historical-calibration-pending","prerequisites":[{"topicId":"poa-s1-lesson-02","requires":["poa-s1-lesson-01"]},{"topicId":"poa-s2-lesson-03","requires":["poa-s1-lesson-02"]},{"topicId":"poa-s2-lesson-04","requires":["poa-s2-lesson-03"]},{"topicId":"poa-s2-lesson-05","requires":["poa-s2-lesson-04"]},{"topicId":"poa-s3-lesson-06","requires":["poa-s2-lesson-05"]},{"topicId":"poa-s3-lesson-07","requires":["poa-s3-lesson-06"]},{"topicId":"poa-s3-lesson-08","requires":["poa-s3-lesson-07"]},{"topicId":"poa-s3-lesson-09","requires":["poa-s3-lesson-08"]},{"topicId":"poa-s4-lesson-10","requires":["poa-s3-lesson-09"]},{"topicId":"poa-s4-lesson-11","requires":["poa-s4-lesson-10"]},{"topicId":"poa-s5-lesson-12","requires":["poa-s4-lesson-11"]},{"topicId":"poa-s5-lesson-13","requires":["poa-s5-lesson-12"]},{"topicId":"poa-s5-lesson-14","requires":["poa-s5-lesson-13"]},{"topicId":"poa-s6-lesson-15","requires":["poa-s5-lesson-14"]},{"topicId":"poa-s6-lesson-16","requires":["poa-s6-lesson-15"]},{"topicId":"poa-s6-lesson-17","requires":["poa-s6-lesson-16"]},{"topicId":"poa-s7-lesson-18","requires":["poa-s6-lesson-17"]},{"topicId":"poa-s7-lesson-19","requires":["poa-s7-lesson-18"]},{"topicId":"poa-s7-lesson-20","requires":["poa-s7-lesson-19"]},{"topicId":"poa-s8-lesson-21","requires":["poa-s7-lesson-20"]},{"topicId":"poa-s8-lesson-22","requires":["poa-s8-lesson-21"]},{"topicId":"poa-s8-lesson-23","requires":["poa-s8-lesson-22"]},{"topicId":"poa-s9-lesson-24","requires":["poa-s8-lesson-23"]},{"topicId":"poa-s9-lesson-25","requires":["poa-s9-lesson-24"]},{"topicId":"poa-s9-lesson-26","requires":["poa-s9-lesson-25"]},{"topicId":"poa-s10-lesson-27","requires":["poa-s9-lesson-26"]},{"topicId":"poa-s10-lesson-28","requires":["poa-s10-lesson-27"]},{"topicId":"poa-s10-lesson-29","requires":["poa-s10-lesson-28"]},{"topicId":"poa-s11-lesson-30","requires":["poa-s10-lesson-29"]},{"topicId":"poa-s11-lesson-31","requires":["poa-s11-lesson-30"]},{"topicId":"poa-s11-lesson-32","requires":["poa-s11-lesson-31"]},{"topicId":"poa-s11-lesson-33","requires":["poa-s11-lesson-32"]}]}'::jsonb,1)
