insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s1-lesson-01','poa-section-1','What accounting tells us','Accounting means identifying, recording, classifying, summarising and interpreting financial transactions. Bookkeeping is the recording part; accounting also explains what the records mean. A transaction is an event that changes the money, property, obligations or ownership interest of a business. Buying stock, selling goods and paying rent are transactions. An enquiry about prices is not yet a transaction.',0,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":7,"section":1,"objectiveCodes":["S1.1","S1.2"]},"lesson":{"introduction":"Accounting means identifying, recording, classifying, summarising and interpreting financial transactions. Bookkeeping is the recording part; accounting also explains what the records mean. A transaction is an event that changes the money, property, obligations or ownership interest of a business. Buying stock, selling goods and paying rent are transactions. An enquiry about prices is not yet a transaction.","objectives":["explain the concept and purposes of Accounting","identify the users of accounting information"],"sections":[{"title":"Understand the idea","paragraphs":["Think of a small shop in Montego Bay. Its owner needs to know whether sales cover costs, how much customers owe and whether enough cash will be available to pay suppliers. Records support planning, control, accountability and decisions. Profit measures performance over a period. A balance sheet shows financial position on one date. Neither replaces the other.","Internal users include owners and managers deciding prices, staffing and expansion. External users include lenders assessing repayment, suppliers considering credit, investors assessing returns, employees considering security, and government agencies checking required returns. Match the information to the decision: a lender needs cash and debt information, while a manager comparing products needs costs and margins."]},{"title":"Worked example","paragraphs":["A shop receives $8,000 from customers but spends $6,000 on stock and $1,000 on rent. The cash movement is +$1,000. You cannot call this net profit without knowing how much stock was sold, any credit sales and unpaid expenses."]},{"title":"Common mistake","paragraphs":["Money received is not always revenue: an owner''s investment or bank loan also increases cash."]}],"keyPoints":["Liquidity, existing debts and payment history help the supplier assess whether the business can pay on time.","Money received is not always revenue: an owner''s investment or bank loan also increases cash."],"summary":"Check your understanding: A supplier is deciding whether to allow 30 days to pay. What information matters?","check":{"question":"A supplier is deciding whether to allow 30 days to pay. What information matters?","answer":"Liquidity, existing debts and payment history help the supplier assess whether the business can pay on time."},"flashcards":[{"front":"A supplier is deciding whether to allow 30 days to pay. What information matters?","back":"Liquidity, existing debts and payment history help the supplier assess whether the business can pay on time."},{"front":"What mistake should you avoid when studying what accounting tells us?","back":"Money received is not always revenue: an owner''s investment or bank loan also increases cash."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s1-lesson-02','poa-section-1','Careers, trust and ethical choices','Accounting work includes bookkeeping, payroll, financial accounting, management accounting, auditing, taxation and forensic investigation. A bookkeeper records transactions; a management accountant helps managers plan and control; an auditor examines evidence; a forensic accountant investigates suspected financial misconduct. Banks, insurers, businesses and entrepreneurs all use accounting skills. Digital systems also create roles in financial data analysis and systems control.',1,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":7,"section":1,"objectiveCodes":["S1.3","S1.4"]},"lesson":{"introduction":"Accounting work includes bookkeeping, payroll, financial accounting, management accounting, auditing, taxation and forensic investigation. A bookkeeper records transactions; a management accountant helps managers plan and control; an auditor examines evidence; a forensic accountant investigates suspected financial misconduct. Banks, insurers, businesses and entrepreneurs all use accounting skills. Digital systems also create roles in financial data analysis and systems control.","objectives":["describe traditional and emerging careers in the field of Accounting","discuss ethical issues in the field of Accounting."],"sections":[{"title":"Understand the idea","paragraphs":["Integrity means being honest, including when an error makes the business look better. Objectivity means resisting bias and conflicts of interest. Professional competence means keeping skills current and recognising limits. Confidentiality means protecting information except where authorised or required to disclose it. Professional behaviour means following relevant rules and avoiding conduct that discredits the profession.","If a manager asks you to hide an unpaid bill, keep the evidence, explain that the liability belongs in the records, and use the organisation''s reporting process. Do not change a record just to please someone. Deliberate falsification can cause bad lending decisions, loss of trust, disciplinary action and legal consequences. Ethical reasoning should explain the action, the principle affected and the likely harm."]},{"title":"Worked example","paragraphs":["A payroll clerk sends employees'' salaries to a friend. Even if the amounts are correct, sharing confidential information without authority breaches confidentiality. Restrict access and report the disclosure through the proper process."]},{"title":"Common mistake","paragraphs":["An instruction from a senior employee does not make a false entry acceptable."]}],"keyPoints":["Objectivity: the personal connection creates a conflict that should be disclosed and managed.","An instruction from a senior employee does not make a false entry acceptable."],"summary":"Check your understanding: Which ethical principle is threatened when an accountant favours a supplier owned by a relative?","check":{"question":"Which ethical principle is threatened when an accountant favours a supplier owned by a relative?","answer":"Objectivity: the personal connection creates a conflict that should be disclosed and managed."},"flashcards":[{"front":"Which ethical principle is threatened when an accountant favours a supplier owned by a relative?","back":"Objectivity: the personal connection creates a conflict that should be disclosed and managed."},{"front":"What mistake should you avoid when studying careers, trust and ethical choices?","back":"An instruction from a senior employee does not make a false entry acceptable."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s2-lesson-03','poa-section-2','The rules and the accounting cycle','The separate entity concept treats the business''s records separately from the owner''s personal affairs. A sole trader''s personal groceries are drawings, not a business expense. Accruals recognise income when earned and expenses when incurred, rather than simply when money changes hands. Matching puts expenses against the revenue of the appropriate period.',2,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":9,"section":2,"objectiveCodes":["S2.1","S2.2"]},"lesson":{"introduction":"The separate entity concept treats the business''s records separately from the owner''s personal affairs. A sole trader''s personal groceries are drawings, not a business expense. Accruals recognise income when earned and expenses when incurred, rather than simply when money changes hands. Matching puts expenses against the revenue of the appropriate period.","objectives":["outline the concepts and conventions that guide the accounting process","describe the accounting cycle"],"sections":[{"title":"Understand the idea","paragraphs":["Prudence means exercising care under uncertainty: do not overstate assets or income or understate liabilities or expenses. It does not mean deliberately understating profit. Consistency means using comparable methods from period to period; a justified change must be explained. These ideas make records more useful than a list of cash movements alone.","Follow the accounting cycle: transaction → source document → book of original entry → ledger → trial balance → adjustments → financial statements → closing entries. A receipt provides evidence; a day book groups similar transactions; ledger accounts collect changes for each account; the trial balance checks debit and credit totals. Adjustments bring the records into the correct period before statements are prepared."]},{"title":"Worked example","paragraphs":["December electricity of $900 is paid in January. December''s expense is still $900: debit electricity expense and credit accrued electricity $900. January payment clears the liability instead of creating December''s expense again."]},{"title":"Common mistake","paragraphs":["A balanced trial balance checks arithmetic agreement; it does not prove every transaction is correct."]}],"keyPoints":["Debit drawings and credit cash. The separate entity concept keeps the personal cost out of business expenses.","A balanced trial balance checks arithmetic agreement; it does not prove every transaction is correct."],"summary":"Check your understanding: The owner pays a personal phone bill from business cash. What is the entry?","check":{"question":"The owner pays a personal phone bill from business cash. What is the entry?","answer":"Debit drawings and credit cash. The separate entity concept keeps the personal cost out of business expenses."},"flashcards":[{"front":"The owner pays a personal phone bill from business cash. What is the entry?","back":"Debit drawings and credit cash. The separate entity concept keeps the personal cost out of business expenses."},{"front":"What mistake should you avoid when studying the rules and the accounting cycle?","back":"A balanced trial balance checks arithmetic agreement; it does not prove every transaction is correct."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s2-lesson-04','poa-section-2','Business types, statements and technology','A sole trader has one owner and a capital account. A partnership has partners whose agreement governs profit sharing and capital. A company has shareholders and separate legal identity. A cooperative serves members through joint ownership and democratic participation. A non-profit organisation aims to provide services rather than distribute business profits to owners. The organisation''s purpose changes the statements and equity labels it uses.',3,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":9,"section":2,"objectiveCodes":["S2.3","S2.4","S2.5"]},"lesson":{"introduction":"A sole trader has one owner and a capital account. A partnership has partners whose agreement governs profit sharing and capital. A company has shareholders and separate legal identity. A cooperative serves members through joint ownership and democratic participation. A non-profit organisation aims to provide services rather than distribute business profits to owners. The organisation''s purpose changes the statements and equity labels it uses.","objectives":["appraise the accounting features of various types of business organisations","identify the main financial statements prepared by various business organisations;","assess the role and impact of technology on the accounting process"],"sections":[{"title":"Understand the idea","paragraphs":["An income statement reports revenue, expenses and profit over a period. A balance sheet reports assets, liabilities and equity on a date. A cash flow statement explains movements in cash. A non-profit income and expenditure account measures the period''s surplus or deficit on an accrual basis; a receipts and payments account lists cash movements. Do not confuse those two accounts.","Software can process payroll, inventory, receivables and payables quickly, generate reports and reduce repeated arithmetic. Spreadsheets allow flexible calculations; accounting packages link records and keep audit trails. Automation still depends on correct source data, suitable account codes and controlled access. Use backups, permissions, reconciliations and review. A wrong formula or duplicated invoice can spread errors through many reports, while outages, security failures and training costs also matter."]},{"title":"Worked example","paragraphs":["A credit union records member shares and loans; a school club records subscriptions and cash spent on events. Both need reliable records, but the club''s receipts and payments account is not a company''s profit appropriation account."]},{"title":"Common mistake","paragraphs":["Software does not decide whether a personal purchase belongs in business expenses."]}],"keyPoints":["Customers may not have paid credit sales, or cash may have been spent on equipment, inventory, drawings or loan repayments.","Software does not decide whether a personal purchase belongs in business expenses."],"summary":"Check your understanding: Why might a business earn profit but have little cash?","check":{"question":"Why might a business earn profit but have little cash?","answer":"Customers may not have paid credit sales, or cash may have been spent on equipment, inventory, drawings or loan repayments."},"flashcards":[{"front":"Why might a business earn profit but have little cash?","back":"Customers may not have paid credit sales, or cash may have been spent on equipment, inventory, drawings or loan repayments."},{"front":"What mistake should you avoid when studying business types, statements and technology?","back":"Software does not decide whether a personal purchase belongs in business expenses."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s2-lesson-05','poa-section-2','Assets, liabilities and the balance sheet','An asset is a resource controlled by the business from which future benefits are expected. A liability is an obligation owed to others. Capital is the owner''s residual interest: assets minus liabilities. The accounting equation is assets = capital + liabilities. Every recorded transaction must preserve this equality, although several items may change at once.',4,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":10,"section":2,"objectiveCodes":["S2.6","S2.7","S2.8","S2.9","S2.10"]},"lesson":{"introduction":"An asset is a resource controlled by the business from which future benefits are expected. A liability is an obligation owed to others. Capital is the owner''s residual interest: assets minus liabilities. The accounting equation is assets = capital + liabilities. Every recorded transaction must preserve this equality, although several items may change at once.","objectives":["explain the concept of a Balance Sheet and the balance sheet equation","identify the components of a Balance Sheet","give examples of different types of assets and liabilities","construct Balance Sheets","determine which items in a Balance Sheet will change as a result of various transactions."],"sections":[{"title":"Understand the idea","paragraphs":["Non-current assets such as equipment are held for continuing use. Current assets such as inventory, trade receivables, bank and cash are expected to turn into cash, be sold or be used within the operating cycle or relevant short-term period. Current liabilities such as trade payables and a short-term overdraft fall due soon. A long-term loan is a non-current liability, but the portion due soon is current when classification is required.","Head a balance sheet with the business name, statement title and date. In vertical form list non-current assets, then current assets, deduct current liabilities to find working capital, add net non-current assets and deduct non-current liabilities to arrive at net assets. Reconcile net assets to closing capital. In an order of permanence, longer-held assets come first; in liquidity order, the easiest to convert to cash come first. Label the basis clearly."]},{"title":"Worked example","paragraphs":["Keisha invests $40,000 cash and borrows $10,000. Assets $50,000 = capital $40,000 + liabilities $10,000. Buying a $12,000 refrigerator for cash leaves total assets $50,000: equipment rises $12,000 and cash falls $12,000. Buying $3,000 inventory on credit increases assets and liabilities by $3,000 each."]},{"title":"Common mistake","paragraphs":["A loan is a liability, not income. Buying an asset for cash does not necessarily change total assets."]}],"keyPoints":["Capital = $96,000 − $31,000 = $65,000.","A loan is a liability, not income. Buying an asset for cash does not necessarily change total assets."],"summary":"Check your understanding: Assets are $96,000 and liabilities are $31,000. Find capital.","check":{"question":"Assets are $96,000 and liabilities are $31,000. Find capital.","answer":"Capital = $96,000 − $31,000 = $65,000."},"flashcards":[{"front":"Assets are $96,000 and liabilities are $31,000. Find capital.","back":"Capital = $96,000 − $31,000 = $65,000."},{"front":"What mistake should you avoid when studying assets, liabilities and the balance sheet?","back":"A loan is a liability, not income. Buying an asset for cash does not necessarily change total assets."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s3-lesson-06','poa-section-3','From source documents to day books','Books of original entry organise transactions before posting to ledger accounts. The sales day book records credit sales of goods normally traded. The purchases day book records credit purchases of trading goods. Returns inwards records customer returns; returns outwards records returns to suppliers. The cash book records cash and bank receipts and payments; petty cash records small payments. The general journal records entries that do not belong in those specialised books.',5,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":12,"section":3,"objectiveCodes":["S3.1","S3.2","S3.3"]},"lesson":{"introduction":"Books of original entry organise transactions before posting to ledger accounts. The sales day book records credit sales of goods normally traded. The purchases day book records credit purchases of trading goods. Returns inwards records customer returns; returns outwards records returns to suppliers. The cash book records cash and bank receipts and payments; petty cash records small payments. The general journal records entries that do not belong in those specialised books.","objectives":["explain the uses of books of original entry","distinguish between cash and credit transactions","identify source documents related to books of original entry;"],"sections":[{"title":"Understand the idea","paragraphs":["A cash transaction is settled immediately; a credit transaction creates an amount to be paid later. A debit card normally moves bank funds immediately. A credit card payment creates a settlement relationship with the card provider or bank; read the question''s facts rather than assuming it means a sale on trade credit to the customer. Cheques and electronic transfers belong in the bank column, not physical cash.","An invoice states goods, quantities, prices, discounts, date and parties. A credit note reduces the amount owed, commonly after returns. A debit note can notify or request an adjustment; check who issued it and what happened. A receipt acknowledges payment and a petty cash voucher supports a small payment. Always work from the business whose books you are preparing: its purchase invoice is the seller''s sales invoice."]},{"title":"Worked example","paragraphs":["A furniture retailer buys ten chairs for resale on 30-day credit: purchases day book. It buys an office computer on credit: general journal, because the computer is a non-current asset. A customer pays an old debt by transfer: cash book, bank receipts."]},{"title":"Common mistake","paragraphs":["The purchases day book is not a list of everything bought. It normally contains credit purchases of trading goods."]}],"keyPoints":["A credit note, reducing the customer''s amount owed.","The purchases day book is not a list of everything bought. It normally contains credit purchases of trading goods."],"summary":"Check your understanding: Which document would a seller issue when accepting returned goods?","check":{"question":"Which document would a seller issue when accepting returned goods?","answer":"A credit note, reducing the customer''s amount owed."},"flashcards":[{"front":"Which document would a seller issue when accepting returned goods?","back":"A credit note, reducing the customer''s amount owed."},{"front":"What mistake should you avoid when studying from source documents to day books?","back":"The purchases day book is not a list of everything bought. It normally contains credit purchases of trading goods."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s3-lesson-07','poa-section-3','Prepare documents, record and post totals','To prepare an invoice, enter a unique reference, date, seller, buyer, descriptions, quantities and unit prices. Multiply quantities by prices, deduct trade discounts and show the total due. Add only taxes or charges specified in the question. A credit note should identify the original invoice and the returned or overcharged items. A receipt should identify the payer, date, payment method and amount.',6,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":13,"section":3,"objectiveCodes":["S3.4","S3.5","S3.6","S3.11"]},"lesson":{"introduction":"To prepare an invoice, enter a unique reference, date, seller, buyer, descriptions, quantities and unit prices. Multiply quantities by prices, deduct trade discounts and show the total due. Add only taxes or charges specified in the question. A credit note should identify the original invoice and the returned or overcharged items. A receipt should identify the payer, date, payment method and amount.","objectives":["prepare source documents for use in transaction descriptions","translate source documents into transaction descriptions","use source documents to make entries into books of original entry","indicate treatment of totals from books of original entry."],"sections":[{"title":"Understand the idea","paragraphs":["Translate the document into a short transaction: who bought or sold, what changed, whether settlement was immediate, and the amount after trade discount. Enter it once in the correct original-entry book. Keep the date, document reference, other party and net amount so the entry can be traced. Do not record the same sale again when the customer later pays it; the later event settles a receivable.","Post sales day book totals by debiting the relevant receivables control or individual customers and crediting sales in the appropriate ledger system. Purchases totals debit purchases and credit payables. Sales returns debit returns inwards and credit receivables; purchases returns debit payables and credit returns outwards. Individual customer and supplier postings keep personal accounts accurate. A control-account system requires corresponding subsidiary records; control totals are not extra customer debts."]},{"title":"Worked example","paragraphs":["Invoice 014: 8 bags at $2,500 = $20,000, less 10% trade discount $2,000, net $18,000. For the buyer''s credit purchase of resale goods: debit purchases $18,000, credit supplier $18,000. Returning two bags at the same net price produces a $4,500 credit note."]},{"title":"Common mistake","paragraphs":["Record the net invoice amount. Do not post the trade discount to a separate discount account."]}],"keyPoints":["Debit trade receivables/control $47,000 and credit sales $47,000; update individual customer records as required.","Record the net invoice amount. Do not post the trade discount to a separate discount account."],"summary":"Check your understanding: A sales day book totals $47,000. State the general ledger effect.","check":{"question":"A sales day book totals $47,000. State the general ledger effect.","answer":"Debit trade receivables/control $47,000 and credit sales $47,000; update individual customer records as required."},"flashcards":[{"front":"A sales day book totals $47,000. State the general ledger effect.","back":"Debit trade receivables/control $47,000 and credit sales $47,000; update individual customer records as required."},{"front":"What mistake should you avoid when studying prepare documents, record and post totals?","back":"Record the net invoice amount. Do not post the trade discount to a separate discount account."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s3-lesson-08','poa-section-3','Trade discounts and settlement discounts','A trade discount reduces a list price before the transaction is recorded. It can reward bulk buying or trade relationships. A cash or settlement discount rewards payment within stated terms. Record the trade discount first; calculate any settlement discount on the remaining qualifying debt, following the question''s terms.',7,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":13,"section":3,"objectiveCodes":["S3.7","S3.8"]},"lesson":{"introduction":"A trade discount reduces a list price before the transaction is recorded. It can reward bulk buying or trade relationships. A cash or settlement discount rewards payment within stated terms. Record the trade discount first; calculate any settlement discount on the remaining qualifying debt, following the question''s terms.","objectives":["distinguish between trade and cash discounts","distinguish between discounts allowed and discounts received"],"sections":[{"title":"Understand the idea","paragraphs":["From the seller''s view, discount allowed is the reduction given to a customer for prompt settlement. It is normally a debit expense in these examination accounts. From the buyer''s view, discount received reduces what is paid to a supplier and is a credit income item. The words allowed and received describe the business''s perspective, not the movement of cash alone.","In a three-column cash book, discount allowed appears on the receipts side beside the amount received; discount received appears on the payments side beside the amount paid. The bank or cash amount plus settlement discount clears the whole debt. Discount columns are totalled and posted to the appropriate ledger accounts. They are not balanced like cash and bank columns."]},{"title":"Worked example","paragraphs":["List price $10,000 less 20% trade discount gives an $8,000 invoice. A further 5% settlement discount is $400, so the customer pays $7,600. Seller: debit bank $7,600, debit discount allowed $400, credit customer $8,000. Buyer: debit supplier $8,000, credit bank $7,600, credit discount received $400."]},{"title":"Common mistake","paragraphs":["20% followed by 5% is not a 25% discount: each percentage has a different base."]}],"keyPoints":["$5,880; the $120 discount allowed and $5,880 receipt together clear $6,000.","20% followed by 5% is not a 25% discount: each percentage has a different base."],"summary":"Check your understanding: A customer owes $6,000 and receives 2% discount for paying now. How much enters bank?","check":{"question":"A customer owes $6,000 and receives 2% discount for paying now. How much enters bank?","answer":"$5,880; the $120 discount allowed and $5,880 receipt together clear $6,000."},"flashcards":[{"front":"A customer owes $6,000 and receives 2% discount for paying now. How much enters bank?","back":"$5,880; the $120 discount allowed and $5,880 receipt together clear $6,000."},{"front":"What mistake should you avoid when studying trade discounts and settlement discounts?","back":"20% followed by 5% is not a 25% discount: each percentage has a different base."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s3-lesson-09','poa-section-3','Cash books, contra entries and petty cash','The debit side of the cash book records money coming in; the credit side records money going out. A two-column book has cash and bank; a three-column book adds discount. The cash book is both a book of original entry and a ledger account, so do not create a duplicate bank ledger posting. Cash cannot have a credit balance because physical cash cannot be below zero; bank can show an overdraft.',8,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":13,"section":3,"objectiveCodes":["S3.9","S3.10"]},"lesson":{"introduction":"The debit side of the cash book records money coming in; the credit side records money going out. A two-column book has cash and bank; a three-column book adds discount. The cash book is both a book of original entry and a ledger account, so do not create a duplicate bank ledger posting. Cash cannot have a credit balance because physical cash cannot be below zero; bank can show an overdraft.","objectives":["balance cash books","interpret the balances of the cash books"],"sections":[{"title":"Understand the idea","paragraphs":["A contra entry transfers money between business cash and business bank. For cash lodged, debit bank and credit cash; for a withdrawal for office cash, debit cash and credit bank. Mark both entries C. A withdrawal for the owner''s private use is drawings, not a contra transfer. Balance each cash or bank column separately: put balance carried down on the smaller side to equalise totals, then bring the balance down on the opposite side for the next period.","Under the imprest system, petty cash starts with a fixed float. Record each supported payment in the total and the correct analysis column, such as postage or travel. Reimbursement restores the agreed float. The reimbursement equals supported expenditure if the float is unchanged and there are no shortages. Count the cash and reconcile it to the record; a voucher is evidence of expenditure, not extra cash."]},{"title":"Worked example","paragraphs":["A $5,000 petty cash float pays postage $800 and travel $1,250. Total spent $2,050; cash remaining $2,950; reimbursement $2,050 restores $5,000. If the float rises to $6,000, reimbursement becomes $3,050."]},{"title":"Common mistake","paragraphs":["A debit bank balance in the business cash book normally means money available; a bank statement describes the bank''s opposite perspective."]}],"keyPoints":["No. Debit bank $3,000 and credit cash $3,000: total business money is unchanged.","A debit bank balance in the business cash book normally means money available; a bank statement describes the bank''s opposite perspective."],"summary":"Check your understanding: Cash of $3,000 is deposited into the business bank. Is it income?","check":{"question":"Cash of $3,000 is deposited into the business bank. Is it income?","answer":"No. Debit bank $3,000 and credit cash $3,000: total business money is unchanged."},"flashcards":[{"front":"Cash of $3,000 is deposited into the business bank. Is it income?","back":"No. Debit bank $3,000 and credit cash $3,000: total business money is unchanged."},{"front":"What mistake should you avoid when studying cash books, contra entries and petty cash?","back":"A debit bank balance in the business cash book normally means money available; a bank statement describes the bank''s opposite perspective."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s4-lesson-10','poa-section-4','Double entry without guessing','Debit means left and credit means right. Neither word automatically means good, bad, increase or decrease. Asset and expense increases are debits. Liability, capital and income increases are credits. Decreases use the opposite side. Drawings reduce the owner''s interest and are normally debit entries. For every transaction, total debits must equal total credits.',9,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":15,"section":4,"objectiveCodes":["S4.1","S4.2","S4.3","S4.4"]},"lesson":{"introduction":"Debit means left and credit means right. Neither word automatically means good, bad, increase or decrease. Asset and expense increases are debits. Liability, capital and income increases are credits. Decreases use the opposite side. Drawings reduce the owner''s interest and are normally debit entries. For every transaction, total debits must equal total credits.","objectives":["describe the different classes of accounts","identify the different types of ledgers","explain the significance of debit and credit in each class of account","draw up simple account formats, neatly and accurately"],"sections":[{"title":"Understand the idea","paragraphs":["Nominal accounts contain income and expenses; real accounts contain assets; personal accounts record persons or organisations, including customer receivables and supplier payables. The sales ledger holds individual customer accounts, the purchases ledger individual suppliers, and the general ledger the remaining accounts. An account has its name, date, details, reference and amount on debit and credit sides, or a clearly labelled running-balance equivalent.","Use a three-step method: identify the accounts, decide how each changes, then apply the rule for its category. For cash sales, bank or cash increases and sales income increases: debit cash, credit sales. For paying rent, expense increases and bank decreases: debit rent, credit bank. A credit purchase increases purchases and the supplier liability: debit purchases, credit supplier. Explain the economic event before choosing sides."]},{"title":"Worked example","paragraphs":["A customer pays $2,400 owed from last month. Bank is an asset increasing, so debit bank $2,400. The customer''s debt is an asset decreasing, so credit receivables $2,400. Sales is untouched because it was recorded when earned."]},{"title":"Common mistake","paragraphs":["The bank statement''s debit and credit labels cannot be copied mechanically into the business''s cash book."]}],"keyPoints":["Debit equipment $9,000 and credit the equipment supplier/payable $9,000.","The bank statement''s debit and credit labels cannot be copied mechanically into the business''s cash book."],"summary":"Check your understanding: Equipment costing $9,000 is bought on credit. Name the debit and credit.","check":{"question":"Equipment costing $9,000 is bought on credit. Name the debit and credit.","answer":"Debit equipment $9,000 and credit the equipment supplier/payable $9,000."},"flashcards":[{"front":"Equipment costing $9,000 is bought on credit. Name the debit and credit.","back":"Debit equipment $9,000 and credit the equipment supplier/payable $9,000."},{"front":"What mistake should you avoid when studying double entry without guessing?","back":"The bank statement''s debit and credit labels cannot be copied mechanically into the business''s cash book."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s4-lesson-11','poa-section-4','Posting, balancing and trial balance','Post from original-entry books with a reference and the other account''s name. For a customer, debit credit sales and credit receipts, returns and discounts allowed. For a supplier, credit purchases and debit payments, returns and discounts received. Work chronologically and check each entry against the source. A customer credit balance can mean an overpayment; a supplier debit balance can mean money owed back to the business.',10,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":15,"section":4,"objectiveCodes":["S4.5","S4.6","S4.7","S4.8","S4.9"]},"lesson":{"introduction":"Post from original-entry books with a reference and the other account''s name. For a customer, debit credit sales and credit receipts, returns and discounts allowed. For a supplier, credit purchases and debit payments, returns and discounts received. Work chronologically and check each entry against the source. A customer credit balance can mean an overpayment; a supplier debit balance can mean money owed back to the business.","objectives":["post from books of original entry to the general ledger and the subsidiary ledgers","balance and close accounts","interpret entries and balances","use the balances brought down to construct the trial balance","outline the uses and limitations of the trial balance."],"sections":[{"title":"Understand the idea","paragraphs":["To balance an account, total each side, subtract the smaller total from the larger, enter balance c/d on the smaller side and total both equally. Bring that balance down on the other side in the new period. Income and expense accounts are closed to the income statement at period end; do not automatically carry them forward like assets and liabilities. Drawings close to capital.","A trial balance lists ledger balances at a date in debit and credit columns. Use balances, not the sums of all account entries. Cash, receivables, purchases, expenses and drawings are normally debit; capital, liabilities and income normally credit. Equal totals help detect one-sided postings and arithmetic mistakes. They do not detect complete omission, an entry in the wrong account of the same type, an error of principle, complete reversal, or equal errors on both sides."]},{"title":"Worked example","paragraphs":["Customer account: opening debt $6,000 + sales $4,000 = debit $10,000. Receipts $7,000 and returns $500 total credit $7,500. Put balance c/d $2,500 on credit; next period bring down $2,500 debit. This is the amount still owed."]},{"title":"Common mistake","paragraphs":["Forcing an unexplained difference into an expense account hides the problem. Investigate it or use an explicitly temporary suspense account."]}],"keyPoints":["Yes. Both are expense accounts, so debit and credit totals agree despite the incorrect classification.","Forcing an unexplained difference into an expense account hides the problem. Investigate it or use an explicitly temporary suspense account."],"summary":"Check your understanding: Rent $700 was debited to repairs and bank correctly credited. Will the trial balance agree?","check":{"question":"Rent $700 was debited to repairs and bank correctly credited. Will the trial balance agree?","answer":"Yes. Both are expense accounts, so debit and credit totals agree despite the incorrect classification."},"flashcards":[{"front":"Rent $700 was debited to repairs and bank correctly credited. Will the trial balance agree?","back":"Yes. Both are expense accounts, so debit and credit totals agree despite the incorrect classification."},{"front":"What mistake should you avoid when studying posting, balancing and trial balance?","back":"Forcing an unexplained difference into an expense account hides the problem. Investigate it or use an explicitly temporary suspense account."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s5-lesson-12','poa-section-5','Build a sole trader''s income statement','An income statement explains profit for a period. Start with net sales: sales less returns inwards. Calculate cost of goods sold: opening inventory + net purchases + carriage inwards − closing inventory. Net purchases are purchases less returns outwards. Carriage inwards brings inventory to the business and is included in its cost; carriage outwards delivers sales to customers and is a selling expense.',11,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":17,"section":5,"objectiveCodes":["S5.1","S5.2","S5.3"]},"lesson":{"introduction":"An income statement explains profit for a period. Start with net sales: sales less returns inwards. Calculate cost of goods sold: opening inventory + net purchases + carriage inwards − closing inventory. Net purchases are purchases less returns outwards. Carriage inwards brings inventory to the business and is included in its cost; carriage outwards delivers sales to customers and is a selling expense.","objectives":["explain the purpose of preparing financial statements","identify the components of the Financial Statements","draw up the income statement for sole traders to determine gross profit or loss and net profit or loss"],"sections":[{"title":"Understand the idea","paragraphs":["Gross profit = net sales − cost of goods sold. Add other income and deduct operating expenses to find net profit. Expenses can include rent, wages, advertising, carriage outwards, depreciation and bad debts. Apply period-end adjustments before finishing. Give the business name and ''for the year ended'' date. The trading section explains buying and selling goods; the profit and loss section accounts for other income and running costs.","Closing inventory is unsold goods, so its cost is removed from this period''s cost of sales and also shown as a current asset. If closing inventory is overstated, cost of sales is understated and profit overstated. Drawings of goods reduce purchases or the relevant inventory cost account and increase drawings; they are not sales at a profit unless the facts describe an actual sale."]},{"title":"Worked example","paragraphs":["Sales $120,000, returns inwards $4,000, opening inventory $15,000, purchases $70,000, returns outwards $2,000, carriage inwards $3,000 and closing inventory $18,000. Net sales = $116,000; cost of sales = 15,000 + 70,000 − 2,000 + 3,000 − 18,000 = $68,000; gross profit = $48,000. Other income $1,000 less expenses $31,000 gives net profit $18,000."]},{"title":"Common mistake","paragraphs":["Returns inwards reduce sales; returns outwards reduce purchases. Do not swap them."]}],"keyPoints":["Cost of sales falls by $2,000, so profit rises by $2,000.","Returns inwards reduce sales; returns outwards reduce purchases. Do not swap them."],"summary":"Check your understanding: Closing inventory rises by $2,000 with everything else unchanged. What happens to profit?","check":{"question":"Closing inventory rises by $2,000 with everything else unchanged. What happens to profit?","answer":"Cost of sales falls by $2,000, so profit rises by $2,000."},"flashcards":[{"front":"Closing inventory rises by $2,000 with everything else unchanged. What happens to profit?","back":"Cost of sales falls by $2,000, so profit rises by $2,000."},{"front":"What mistake should you avoid when studying build a sole trader''s income statement?","back":"Returns inwards reduce sales; returns outwards reduce purchases. Do not swap them."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s5-lesson-13','poa-section-5','Working capital and closing capital','Working capital = current assets − current liabilities. It measures the net short-term resources available to support operations. Inventory must be bought, customers may take time to pay and wages fall due even before sales are collected. Positive working capital helps, but slow-moving stock or doubtful receivables may still create cash problems. Negative working capital is a warning to investigate rather than a complete diagnosis by itself.',12,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":17,"section":5,"objectiveCodes":["S5.4","S5.5","S5.8"]},"lesson":{"introduction":"Working capital = current assets − current liabilities. It measures the net short-term resources available to support operations. Inventory must be bought, customers may take time to pay and wages fall due even before sales are collected. Positive working capital helps, but slow-moving stock or doubtful receivables may still create cash problems. Negative working capital is a warning to investigate rather than a complete diagnosis by itself.","objectives":["prepare classified balance sheet in vertical style","explain the significance of the working capital for the operation of a business","show the effect of net profit or loss on capital"],"sections":[{"title":"Understand the idea","paragraphs":["In a classified vertical balance sheet, show non-current assets at cost less accumulated depreciation; list current assets; deduct current liabilities for working capital; combine with net non-current assets and deduct non-current liabilities. The result is net assets financed by the owner. Closing capital = opening capital + additional capital + net profit − drawings. Replace net profit with a deduction for a net loss.","A loan repayment can include principal and interest. Principal reduces the liability and bank; interest is an expense. Drawings reduce capital but do not reduce the profit earned by the business. A balance sheet is ''as at'' one date, while the income statement covers a period. Check that net assets equal closing capital; if they do not, trace the underlying balances rather than editing capital to make it fit."]},{"title":"Worked example","paragraphs":["Current assets $38,000 less current liabilities $16,000 give working capital $22,000. Non-current assets $60,000 plus working capital $22,000 less long-term loan $20,000 give net assets $62,000. Opening capital $50,000 + profit $18,000 − drawings $6,000 also equals $62,000."]},{"title":"Common mistake","paragraphs":["Net profit is not the same as the closing capital balance, and drawings are not wages paid to the owner."]}],"keyPoints":["$30,000 + $4,000 − $2,000 − $5,000 = $27,000.","Net profit is not the same as the closing capital balance, and drawings are not wages paid to the owner."],"summary":"Check your understanding: Opening capital $30,000, new investment $4,000, loss $2,000 and drawings $5,000: closing capital?","check":{"question":"Opening capital $30,000, new investment $4,000, loss $2,000 and drawings $5,000: closing capital?","answer":"$30,000 + $4,000 − $2,000 − $5,000 = $27,000."},"flashcards":[{"front":"Opening capital $30,000, new investment $4,000, loss $2,000 and drawings $5,000: closing capital?","back":"$30,000 + $4,000 − $2,000 − $5,000 = $27,000."},{"front":"What mistake should you avoid when studying working capital and closing capital?","back":"Net profit is not the same as the closing capital balance, and drawings are not wages paid to the owner."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s5-lesson-14','poa-section-5','Ratios that lead to useful recommendations','Gross profit margin = gross profit ÷ net sales × 100. Net profit margin = net profit ÷ net sales × 100. Mark-up = gross profit ÷ cost of sales × 100; it uses a different denominator. Average inventory = (opening + closing inventory) ÷ 2. Inventory turnover = cost of sales ÷ average inventory, expressed in times per period. A low turnover can suggest slow stock but depends on the type of business.',13,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":17,"section":5,"objectiveCodes":["S5.6","S5.7","S5.9"]},"lesson":{"introduction":"Gross profit margin = gross profit ÷ net sales × 100. Net profit margin = net profit ÷ net sales × 100. Mark-up = gross profit ÷ cost of sales × 100; it uses a different denominator. Average inventory = (opening + closing inventory) ÷ 2. Inventory turnover = cost of sales ÷ average inventory, expressed in times per period. A low turnover can suggest slow stock but depends on the type of business.","objectives":["use ratios to determine the performance (profitability) of the business","calculate ratios to demonstrate the financial position of a business","make recommendations about a business based on ratio analysis."],"sections":[{"title":"Understand the idea","paragraphs":["Current ratio = current assets ÷ current liabilities. Acid test = (current assets − inventory) ÷ current liabilities. Express these as x:1. Return on capital employed/investment = the relevant profit ÷ capital employed × 100; use the definition, opening/average basis and profit measure requested. Do not silently use sales as the denominator. A ratio with a zero denominator is undefined, not zero.","Compare periods, similar businesses and the information behind the figures. A rising gross margin may reflect higher prices or lower buying costs. A falling net margin despite a steady gross margin points towards operating expenses. Explain the cause as a possibility, then recommend a specific action and acknowledge limitations. Ratios alone do not prove mismanagement or predict survival."]},{"title":"Worked example","paragraphs":["Net sales $100,000, cost of sales $60,000, net profit $10,000 and average inventory $15,000 give gross margin 40%, net margin 10%, mark-up 66.67% and turnover 4 times. Current assets $30,000 including stock $12,000, current liabilities $15,000: current ratio 2:1; acid test 1.2:1. Recommend collecting overdue debts if receivables are tying up cash."]},{"title":"Common mistake","paragraphs":["A 25% mark-up is a 20% margin: cost $100, profit $25, selling price $125."]}],"keyPoints":["Operating expenses relative to sales, along with changes in other income, rather than assuming buying costs caused the whole decline.","A 25% mark-up is a 20% margin: cost $100, profit $25, selling price $125."],"summary":"Check your understanding: Gross margin stays at 30% while net margin falls from 12% to 7%. What should be investigated?","check":{"question":"Gross margin stays at 30% while net margin falls from 12% to 7%. What should be investigated?","answer":"Operating expenses relative to sales, along with changes in other income, rather than assuming buying costs caused the whole decline."},"flashcards":[{"front":"Gross margin stays at 30% while net margin falls from 12% to 7%. What should be investigated?","back":"Operating expenses relative to sales, along with changes in other income, rather than assuming buying costs caused the whole decline."},{"front":"What mistake should you avoid when studying ratios that lead to useful recommendations?","back":"A 25% mark-up is a 20% margin: cost $100, profit $25, selling price $125."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s6-lesson-15','poa-section-6','Accruals and prepayments, step by step','Adjustments put income and expenses in the period to which they belong. An accrued expense has been incurred but not paid: add it to the expense and show a current liability. A prepaid expense has been paid for a future period: deduct it from the expense and show a current asset. The money paid and the period''s cost therefore need not match.',14,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":19,"section":6,"objectiveCodes":["S6.1","S6.2","S6.3","S6.11","S6.12","S6.13"]},"lesson":{"introduction":"Adjustments put income and expenses in the period to which they belong. An accrued expense has been incurred but not paid: add it to the expense and show a current liability. A prepaid expense has been paid for a future period: deduct it from the expense and show a current asset. The money paid and the period''s cost therefore need not match.","objectives":["explain accounting concepts that underpin the need for adjustments","explain why adjustments are made to financial statements","prepare journal entries and ledger accounts to reflect adjustments and the treatment in the balance sheet","determine the amount of expenses or revenues to be transferred to the Income Statement","prepare income statements to reflect adjusting entries","prepare Financial Statements after adjustments"],"sections":[{"title":"Understand the idea","paragraphs":["For an expense, start with cash paid, add closing accrual, subtract opening accrual, add opening prepayment and subtract closing prepayment. For income, start with cash received, add closing accrued income, subtract opening accrued income, add opening income received in advance and subtract closing income received in advance. Write a timeline when dates span years. Apportion evenly only when the question supports that assumption.","Closing expense accrual: debit expense, credit accrued expense. Closing prepayment: debit prepaid expense, credit expense. Accrued income: debit income receivable, credit income. Income received in advance: debit income, credit deferred income. Transfer the adjusted income and expense balances to the income statement, and put the remaining assets and liabilities on the balance sheet. An adjusted trial balance helps you check both sides of each adjustment."]},{"title":"Worked example","paragraphs":["Rent paid $36,000 covers 1 April to 31 March; the business year ends 31 December. Three months belong to next year: prepaid rent = 36,000 × 3/12 = $9,000. This year''s rent from that payment is $27,000. Debit prepaid rent $9,000 and credit rent expense $9,000. Show the $9,000 as a current asset."]},{"title":"Common mistake","paragraphs":["Adding a prepayment to expense charges next year''s cost to this year. Check the period, not just the payment date."]}],"keyPoints":["$21,000 − $1,000 + $2,500 = $22,500. The opening liability belonged to last period.","Adding a prepayment to expense charges next year''s cost to this year. Check the period, not just the payment date."],"summary":"Check your understanding: Wages paid $21,000; opening wages owing $1,000; closing wages owing $2,500. Find wages expense.","check":{"question":"Wages paid $21,000; opening wages owing $1,000; closing wages owing $2,500. Find wages expense.","answer":"$21,000 − $1,000 + $2,500 = $22,500. The opening liability belonged to last period."},"flashcards":[{"front":"Wages paid $21,000; opening wages owing $1,000; closing wages owing $2,500. Find wages expense.","back":"$21,000 − $1,000 + $2,500 = $22,500. The opening liability belonged to last period."},{"front":"What mistake should you avoid when studying accruals and prepayments, step by step?","back":"Adding a prepayment to expense charges next year''s cost to this year. Check the period, not just the payment date."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s6-lesson-16','poa-section-6','Bad debts and doubtful debt allowances','A bad debt is a specific amount judged irrecoverable. A doubtful debt allowance estimates how much of the remaining receivables may not be collected. Customers may become insolvent, dispute balances or repeatedly fail to pay. An aged receivables list groups debts by how long they have been outstanding and supports a reasoned estimate.',15,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":19,"section":6,"objectiveCodes":["S6.4","S6.5","S6.6"]},"lesson":{"introduction":"A bad debt is a specific amount judged irrecoverable. A doubtful debt allowance estimates how much of the remaining receivables may not be collected. Customers may become insolvent, dispute balances or repeatedly fail to pay. An aged receivables list groups debts by how long they have been outstanding and supports a reasoned estimate.","objectives":["explain the reasons for bad debts","prepare journal entries and ledger accounts to write off bad debts and create provision for doubtful debts","indicate the treatment of bad and doubtful debts in the Income Statement and Balance Sheet"],"sections":[{"title":"Understand the idea","paragraphs":["Write off an irrecoverable debt by debiting bad debts expense and crediting the customer''s account or receivables control. Then calculate the required closing allowance on the remaining eligible receivables, using the question''s percentage or specific estimates. To create or increase an allowance, debit doubtful debts expense and credit allowance for doubtful debts. A decrease reverses that movement.","The income statement includes the specific bad debts plus the increase in allowance, or subtracts the decrease. The balance sheet shows trade receivables after write-offs, less the closing allowance. The allowance is a deduction from the asset, not a cash fund or a separate liability owed to someone. Do not charge the full closing allowance as an expense if an opening allowance already exists."]},{"title":"Worked example","paragraphs":["Receivables $40,000 include a $2,000 irrecoverable debt. Write it off, leaving $38,000. Required allowance at 5% = $1,900. If opening allowance was $1,500, the increase is $400. Income statement charge = bad debt $2,000 + increase $400 = $2,400. Balance sheet receivables = $38,000 − $1,900 = $36,100."]},{"title":"Common mistake","paragraphs":["Calculate the percentage after writing off the named bad debt unless the question explicitly says otherwise."]}],"keyPoints":["A $300 decrease: debit allowance and credit the doubtful debts expense/income statement adjustment $300.","Calculate the percentage after writing off the named bad debt unless the question explicitly says otherwise."],"summary":"Check your understanding: Required allowance is $900 and existing allowance is $1,200. What is the period''s movement?","check":{"question":"Required allowance is $900 and existing allowance is $1,200. What is the period''s movement?","answer":"A $300 decrease: debit allowance and credit the doubtful debts expense/income statement adjustment $300."},"flashcards":[{"front":"Required allowance is $900 and existing allowance is $1,200. What is the period''s movement?","back":"A $300 decrease: debit allowance and credit the doubtful debts expense/income statement adjustment $300."},{"front":"What mistake should you avoid when studying bad debts and doubtful debt allowances?","back":"Calculate the percentage after writing off the named bad debt unless the question explicitly says otherwise."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s6-lesson-17','poa-section-6','Depreciation and expenditure','Depreciation allocates a depreciable asset''s cost over its useful life. Wear, use, passage of time and obsolescence can reduce usefulness. It is not a savings fund and does not try to measure an asset''s exact resale value each year. Consider cost, expected residual value and useful life, and follow the stated policy for assets bought during the year.',16,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":19,"section":6,"objectiveCodes":["S6.7","S6.8","S6.9","S6.10"]},"lesson":{"introduction":"Depreciation allocates a depreciable asset''s cost over its useful life. Wear, use, passage of time and obsolescence can reduce usefulness. It is not a savings fund and does not try to measure an asset''s exact resale value each year. Consider cost, expected residual value and useful life, and follow the stated policy for assets bought during the year.","objectives":["discuss the nature of depreciation","calculate annual depreciation expenses using straight line method and reducing balance method;","prepare journal entries and ledger accounts for provision for depreciation","distinguish between capital expenditure and revenue expenditures"],"sections":[{"title":"Understand the idea","paragraphs":["Straight-line annual depreciation = (cost − residual value) ÷ useful life. When the question specifies a percentage of cost, apply that stated rate consistently. Reducing balance depreciation = opening carrying amount × rate. Carrying amount, also called net book value, equals cost less accumulated depreciation. Under reducing balance the charge normally falls each year; straight-line normally gives a constant full-year charge.","Debit depreciation expense and credit accumulated depreciation. Show cost less accumulated depreciation on the balance sheet. Capital expenditure acquires or improves a non-current asset and is initially recorded as an asset; revenue expenditure maintains operations and is charged as an expense. Installation needed to bring new equipment into use can form part of cost; routine repairs normally do not. Misclassifying a repair as an asset overstates profit and assets."]},{"title":"Worked example","paragraphs":["Equipment costs $50,000 with residual value $5,000 and five-year life. Straight-line charge = (50,000 − 5,000)/5 = $9,000 each full year; after two years carrying amount = $32,000. At 20% reducing balance with no separate residual adjustment, year 1 charge $10,000, carrying amount $40,000; year 2 charge $8,000, carrying amount $32,000."]},{"title":"Common mistake","paragraphs":["Use opening carrying amount for reducing balance, not the original cost every year. Do not depreciate below the specified residual value."]}],"keyPoints":["($24,000 − $4,000)/4 = $5,000.","Use opening carrying amount for reducing balance, not the original cost every year. Do not depreciate below the specified residual value."],"summary":"Check your understanding: A machine costs $24,000, residual $4,000, useful life four years. Annual straight-line depreciation?","check":{"question":"A machine costs $24,000, residual $4,000, useful life four years. Annual straight-line depreciation?","answer":"($24,000 − $4,000)/4 = $5,000."},"flashcards":[{"front":"A machine costs $24,000, residual $4,000, useful life four years. Annual straight-line depreciation?","back":"($24,000 − $4,000)/4 = $5,000."},{"front":"What mistake should you avoid when studying depreciation and expenditure?","back":"Use opening carrying amount for reducing balance, not the original cost every year. Do not depreciate below the specified residual value."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s7-lesson-18','poa-section-7','Correcting errors and using suspense','Controls help detect mistakes, protect assets and support reliable reports. Reconciliations compare independent records; authorisation and separation of duties reduce opportunities for error or misuse. A suspense account temporarily holds a trial balance difference while its causes are investigated. It is not income, an expense or a permanent solution.',17,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":21,"section":7,"objectiveCodes":["S7.1","S7.2","S7.3","S7.4","S7.5","S7.6","S7.7"]},"lesson":{"introduction":"Controls help detect mistakes, protect assets and support reliable reports. Reconciliations compare independent records; authorisation and separation of duties reduce opportunities for error or misuse. A suspense account temporarily holds a trial balance difference while its causes are investigated. It is not income, an expense or a permanent solution.","objectives":["explain the uses of control systems in the accounting process","outline the THREE most commonly used control systems in the accounting process","distinguish between those errors which affect and those which do not affect the trial balance","prepare journal entries for the correction of errors","explain the need for suspense account","construct a suspense account","construct a statement of revised profit after the correction of errors"],"sections":[{"title":"Understand the idea","paragraphs":["Errors that disturb debit-credit agreement include a one-sided omission, unequal amounts and putting an amount on the wrong side. Complete omission, wrong-account errors, errors of principle, complete reversal and equal wrong amounts on both sides can leave the trial balance balanced. For each correction, first write the entry that should have been made, compare it with the entry actually made, then record only the difference.","If debit balances exceed credits, a temporary credit suspense balance restores agreement; if credits exceed debits, suspense begins as a debit. Correct known errors with journal entries and post any required suspense entries until its balance is zero. Revise profit only for errors affecting income or expenses. Correcting an asset-to-asset classification changes the balance sheet but not profit. Drawings wrongly treated as an expense understated profit."]},{"title":"Worked example","paragraphs":["Rent $600 was correctly credited to bank but omitted from rent. Credits exceed debits by $600, so suspense initially has a $600 debit. Correct by debit rent $600 and credit suspense $600; profit falls $600. Separately, equipment $2,000 wrongly debited to purchases: debit equipment $2,000, credit purchases $2,000. Profit rises $2,000; no suspense entry is needed."]},{"title":"Common mistake","paragraphs":["Do not use suspense for an error that already has equal debit and credit effects."]}],"keyPoints":["Increase receivables by a $180 debit and sales by a $180 credit. The trial balance had agreed; profit rises $180.","Do not use suspense for an error that already has equal debit and credit effects."],"summary":"Check your understanding: Sales of $750 were recorded on both sides as $570. What correction is required?","check":{"question":"Sales of $750 were recorded on both sides as $570. What correction is required?","answer":"Increase receivables by a $180 debit and sales by a $180 credit. The trial balance had agreed; profit rises $180."},"flashcards":[{"front":"Sales of $750 were recorded on both sides as $570. What correction is required?","back":"Increase receivables by a $180 debit and sales by a $180 credit. The trial balance had agreed; profit rises $180."},{"front":"What mistake should you avoid when studying correcting errors and using suspense?","back":"Do not use suspense for an error that already has equal debit and credit effects."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s7-lesson-19','poa-section-7','Receivables and payables control accounts','A control account summarises a subsidiary ledger so its total can be checked against the list of individual balances. Use independently totalled day books, cash books and journals. If the same inaccurate total is copied into both records, agreement is weaker evidence. Controls help locate errors but do not prove every personal account is correct.',18,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":21,"section":7,"objectiveCodes":["S7.8","S7.9","S7.10","S7.11"]},"lesson":{"introduction":"A control account summarises a subsidiary ledger so its total can be checked against the list of individual balances. Use independently totalled day books, cash books and journals. If the same inaccurate total is copied into both records, agreement is weaker evidence. Controls help locate errors but do not prove every personal account is correct.","objectives":["explain the purposes of control accounts and how they are prepared","identify the sources of information for entries made in control accounts","construct sales and purchases ledger control accounts","explain the significance of the balances on control accounts;"],"sections":[{"title":"Understand the idea","paragraphs":["Receivables control normally begins with a debit. Debit credit sales, dishonoured customer cheques and interest charged where specified. Credit receipts, sales returns, discounts allowed and bad debts. A contra set-off against a supplier account credits receivables control and debits payables control. Do not include cash sales because no customer debt is created.","Payables control normally begins with a credit. Credit credit purchases and any reinstated supplier debts. Debit payments, purchases returns, discounts received and contra set-offs. Calculate the closing balance and compare with the subsidiary ledger schedule. Abnormal opposite-side balances can arise from overpayments and should be shown separately where required rather than silently netted away. A receivables credit balance may mean the business owes a customer a refund."]},{"title":"Worked example","paragraphs":["Receivables: opening $12,000 + credit sales $40,000 − receipts $30,000 − returns $1,000 − discount $500 − bad debt $1,500 = closing debit $19,000. Payables: opening $9,000 + credit purchases $25,000 − payments $20,000 − returns $2,000 − discount received $500 = closing credit $11,500."]},{"title":"Common mistake","paragraphs":["Customer refunds and dishonoured cheques reverse earlier effects; identify what is being reversed before choosing a side."]}],"keyPoints":["A credit sale creates a customer debt. A cash sale is settled immediately and creates no receivable.","Customer refunds and dishonoured cheques reverse earlier effects; identify what is being reversed before choosing a side."],"summary":"Check your understanding: Why is a credit sale included in receivables control but a cash sale excluded?","check":{"question":"Why is a credit sale included in receivables control but a cash sale excluded?","answer":"A credit sale creates a customer debt. A cash sale is settled immediately and creates no receivable."},"flashcards":[{"front":"Why is a credit sale included in receivables control but a cash sale excluded?","back":"A credit sale creates a customer debt. A cash sale is settled immediately and creates no receivable."},{"front":"What mistake should you avoid when studying receivables and payables control accounts?","back":"Customer refunds and dishonoured cheques reverse earlier effects; identify what is being reversed before choosing a side."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s7-lesson-20','poa-section-7','Bank reconciliation that actually reconciles','The cash book is the business''s bank record; the bank statement is the bank''s record. They differ when one side knows about an event first, when clearing takes time, or when an error occurs. Bank charges, standing orders, direct debits, direct credits, interest and dishonoured cheques may appear on the statement before the business records them.',19,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":22,"section":7,"objectiveCodes":["S7.12","S7.13"]},"lesson":{"introduction":"The cash book is the business''s bank record; the bank statement is the bank''s record. They differ when one side knows about an event first, when clearing takes time, or when an error occurs. Bank charges, standing orders, direct debits, direct credits, interest and dishonoured cheques may appear on the statement before the business records them.","objectives":["identify items that will result in differences between cash book and bank statement balances","construct a bank reconciliation statement using the adjusted cash book balance"],"sections":[{"title":"Understand the idea","paragraphs":["First update the cash book for valid transactions missing from it and correct cash book errors. A bank charge reduces the business bank asset; a direct customer deposit increases it. A dishonoured customer cheque reverses the earlier receipt: debit customer and credit bank. Do not adjust the cash book again for a cheque already recorded but not yet presented or a lodgement awaiting bank processing.","Then prepare the reconciliation using only remaining timing differences and bank errors. With a positive adjusted cash book balance, add unpresented cheques and deduct outstanding lodgements to derive the positive bank statement balance. To move from statement to cash book, reverse those signs. Treat overdrafts as signed negative balances to keep the logic consistent. Explain each difference and confirm that the computed balance matches the actual statement."]},{"title":"Worked example","paragraphs":["Cash book $8,000; bank charge $200 not recorded; direct customer receipt $1,000 not recorded. Adjusted cash book = 8,000 − 200 + 1,000 = $8,800. Unpresented cheques $1,500 and outstanding lodgements $2,300 give statement balance 8,800 + 1,500 − 2,300 = $8,000. The equal starting figures had concealed real differences."]},{"title":"Common mistake","paragraphs":["Do not post unpresented cheques into the cash book a second time; they are already recorded there."]}],"keyPoints":["−2,000 + 500 − 300 = −$1,800, a statement overdraft of $1,800.","Do not post unpresented cheques into the cash book a second time; they are already recorded there."],"summary":"Check your understanding: Adjusted cash book is an overdraft $2,000, unpresented cheques $500, outstanding lodgements $300. Statement balance?","check":{"question":"Adjusted cash book is an overdraft $2,000, unpresented cheques $500, outstanding lodgements $300. Statement balance?","answer":"−2,000 + 500 − 300 = −$1,800, a statement overdraft of $1,800."},"flashcards":[{"front":"Adjusted cash book is an overdraft $2,000, unpresented cheques $500, outstanding lodgements $300. Statement balance?","back":"−2,000 + 500 − 300 = −$1,800, a statement overdraft of $1,800."},{"front":"What mistake should you avoid when studying bank reconciliation that actually reconciles?","back":"Do not post unpresented cheques into the cash book a second time; they are already recorded there."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s8-lesson-21','poa-section-8','How partnerships share ownership','A partnership is a business owned by two or more people carrying on business together for profit. It combines resources and skills but can create disagreements. Ordinary partners commonly have unlimited liability and mutual agency: one partner''s authorised business actions can bind the firm. A sole trader has one owner; a company has a separate legal identity and shareholder ownership. Do not assume every partner has identical duties or liability; read the stated partnership type.',20,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":23,"section":8,"objectiveCodes":["S8.1","S8.2","S8.3","S8.4"]},"lesson":{"introduction":"A partnership is a business owned by two or more people carrying on business together for profit. It combines resources and skills but can create disagreements. Ordinary partners commonly have unlimited liability and mutual agency: one partner''s authorised business actions can bind the firm. A sole trader has one owner; a company has a separate legal identity and shareholder ownership. Do not assume every partner has identical duties or liability; read the stated partnership type.","objectives":["define a partnership business","state the features of a partnership","give reasons for establishing partnerships","outline the essential components of a partnership agreement"],"sections":[{"title":"Understand the idea","paragraphs":["Partnerships can raise more capital than one person, share workload, bring complementary expertise and spread decision-making. Disadvantages include shared profit, conflict and dependence on other partners'' actions. Distinguish an active partner who works in the firm from a sleeping partner who invests without daily management. A limited partner''s role depends on the legal arrangement; do not treat limited liability as a feature of all partnerships.","A partnership agreement should state capital contributions, profit and loss ratio, drawings rules, interest on capital, interest on drawings, partner salaries, decision-making and arrangements for changes or disputes. In examination questions use the stated agreement. Do not invent a salary or interest rate because it seems fair. Partner salaries and interest on capital are allocations of partnership profit, not ordinary employee expenses."]},{"title":"Worked example","paragraphs":["A baker contributes baking expertise and $30,000, while a second partner provides delivery experience and $20,000. They agree a 3:2 residual profit ratio and a $6,000 salary for the working partner. The agreement, not equal ownership assumptions, governs the appropriation."]},{"title":"Common mistake","paragraphs":["The capital contribution ratio and profit-sharing ratio can differ."]}],"keyPoints":["It states rights and responsibilities clearly and reduces disputes over capital, drawings, remuneration and profit allocation.","The capital contribution ratio and profit-sharing ratio can differ."],"summary":"Check your understanding: Why record a partnership agreement in writing?","check":{"question":"Why record a partnership agreement in writing?","answer":"It states rights and responsibilities clearly and reduces disputes over capital, drawings, remuneration and profit allocation."},"flashcards":[{"front":"Why record a partnership agreement in writing?","back":"It states rights and responsibilities clearly and reduces disputes over capital, drawings, remuneration and profit allocation."},{"front":"What mistake should you avoid when studying how partnerships share ownership?","back":"The capital contribution ratio and profit-sharing ratio can differ."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s8-lesson-22','poa-section-8','Capital accounts and profit appropriation','Record a partner''s cash contribution by debiting bank and crediting that partner''s capital. Non-cash contributions debit the relevant assets at agreed values; liabilities taken over are credited, with net investment credited to capital. Under fixed capital, routine drawings and profit allocations go through separate current accounts. Under fluctuating capital they change the capital accounts themselves.',21,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":23,"section":8,"objectiveCodes":["S8.5","S8.6","S8.7"]},"lesson":{"introduction":"Record a partner''s cash contribution by debiting bank and crediting that partner''s capital. Non-cash contributions debit the relevant assets at agreed values; liabilities taken over are credited, with net investment credited to capital. Under fixed capital, routine drawings and profit allocations go through separate current accounts. Under fluctuating capital they change the capital accounts themselves.","objectives":["prepare journal entries and ledger accounts to record the capital of partnership","use various methods to share profit/loss among partners","prepare appropriation account of partnerships"],"sections":[{"title":"Understand the idea","paragraphs":["The appropriation account starts with net profit from the income statement. Add interest on drawings, deduct agreed partner salaries and interest on capital, then divide the residual profit or loss in the agreed ratio. These entries distribute profit among owners; they do not change the total operating profit already earned. A partner''s loan interest, where treated as a finance expense under the question''s rules, belongs before appropriation.","For a ratio a:b, divide residual profit by a+b then multiply by each share. If residual profit is negative, allocate that residual loss using the same agreed rule unless otherwise stated. Keep separate columns for partners and check that the total credited allocations, less interest charged on drawings, reconcile to the net profit being shared."]},{"title":"Worked example","paragraphs":["Net profit $50,000. Interest on drawings A $500, B $300 gives $50,800 available. Salaries A $10,000, B $6,000 and interest on capital A $3,000, B $2,000 leave residual $29,800. At 3:2, shares are A $17,880 and B $11,920. A''s net allocation is 10,000 + 3,000 + 17,880 − 500 = $30,380; B''s is $19,620; total $50,000."]},{"title":"Common mistake","paragraphs":["Do not divide the whole net profit first and then add salaries and interest: that allocates too much."]}],"keyPoints":["$12,000 and $6,000 respectively.","Do not divide the whole net profit first and then add salaries and interest: that allocates too much."],"summary":"Check your understanding: Residual profit is $18,000 shared 2:1. What does each partner receive?","check":{"question":"Residual profit is $18,000 shared 2:1. What does each partner receive?","answer":"$12,000 and $6,000 respectively."},"flashcards":[{"front":"Residual profit is $18,000 shared 2:1. What does each partner receive?","back":"$12,000 and $6,000 respectively."},{"front":"What mistake should you avoid when studying capital accounts and profit appropriation?","back":"Do not divide the whole net profit first and then add salaries and interest: that allocates too much."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s8-lesson-23','poa-section-8','Current accounts and partnership balance sheets','A partner''s current account tracks the running amount due between the firm and that partner when capital is fixed. Credit opening credit balances, salaries, interest on capital and profit shares. Debit drawings, interest on drawings and losses. An opening debit remains on the debit side. Balance each account separately; do not offset one partner''s debt against another''s credit without showing the detail.',22,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":23,"section":8,"objectiveCodes":["S8.8","S8.9","S8.10"]},"lesson":{"introduction":"A partner''s current account tracks the running amount due between the firm and that partner when capital is fixed. Credit opening credit balances, salaries, interest on capital and profit shares. Debit drawings, interest on drawings and losses. An opening debit remains on the debit side. Balance each account separately; do not offset one partner''s debt against another''s credit without showing the detail.","objectives":["prepare current account of partners","explain the significance of the brought down balances on partners’ current accounts","prepare balance sheet of partnerships."],"sections":[{"title":"Understand the idea","paragraphs":["A credit current balance means accumulated entitlements exceed drawings: the firm has retained funds belonging to the partner. A debit balance means drawings and charges exceed those entitlements. It reduces the partner''s equity; it is not automatically an operating expense or bad debt. In the balance sheet''s financed-by section show each fixed capital plus or minus current balance.","Prepare the partnership''s assets and external liabilities as for a sole trader. Reconcile net assets with total partners'' equity. Distinguish a partner''s loan from capital when the question provides it: a loan is a liability, while capital is ownership interest. The statement should make clear which balances are fixed capital, current accounts and external obligations."]},{"title":"Worked example","paragraphs":["A has opening current credit $2,000, salary $6,000, interest on capital $1,000, profit share $8,000, drawings $12,000 and interest on drawings $500. Closing current = 2,000 + 6,000 + 1,000 + 8,000 − 12,000 − 500 = $4,500 credit. Fixed capital $30,000 plus current $4,500 gives A''s equity $34,500."]},{"title":"Common mistake","paragraphs":["Drawings are debited to current accounts under fixed capital, not deducted as a trading expense."]}],"keyPoints":["$18,800: deduct the debit current balance from fixed capital.","Drawings are debited to current accounts under fixed capital, not deducted as a trading expense."],"summary":"Check your understanding: Partner B has fixed capital $20,000 and current debit $1,200. Total equity?","check":{"question":"Partner B has fixed capital $20,000 and current debit $1,200. Total equity?","answer":"$18,800: deduct the debit current balance from fixed capital."},"flashcards":[{"front":"Partner B has fixed capital $20,000 and current debit $1,200. Total equity?","back":"$18,800: deduct the debit current balance from fixed capital."},{"front":"What mistake should you avoid when studying current accounts and partnership balance sheets?","back":"Drawings are debited to current accounts under fixed capital, not deducted as a trading expense."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s9-lesson-24','poa-section-9','Companies, cooperatives and member organisations','A limited liability company has a separate legal identity, continuity and ownership divided into shares. Shareholders generally risk their investment rather than all personal property. A private company restricts share transfers and public offers in the relevant way; a public company can raise funds from the public subject to its rules. Advantages include access to capital and continuity; disadvantages include formation costs, reporting requirements and separation of ownership from control.',23,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":25,"section":9,"objectiveCodes":["S9.1","S9.2","S9.3","S9.4","S9.5"]},"lesson":{"introduction":"A limited liability company has a separate legal identity, continuity and ownership divided into shares. Shareholders generally risk their investment rather than all personal property. A private company restricts share transfers and public offers in the relevant way; a public company can raise funds from the public subject to its rules. Advantages include access to capital and continuity; disadvantages include formation costs, reporting requirements and separation of ownership from control.","objectives":["identify the essential features of limited liability companies, co- operatives and non-profit organisations","identify the types of limited liability companies, co-operatives and non- profit organisations","outline the advantages and disadvantages of a limited liability company","describe the various methods of raising capital available to limited liability companies and co- operatives","identify the various types of shares and the rights of the owners of each type of share"],"sections":[{"title":"Understand the idea","paragraphs":["Ordinary shareholders normally have voting rights and a variable residual return. Preference shares normally receive a specified dividend before ordinary dividends, subject to their terms. Cumulative preference shares may carry arrears forward. Shares are equity. Debentures and bank loans are debt: interest is a finance cost, and principal remains repayable. A debenture holder is a lender, not automatically a voting owner.","Cooperatives are member-owned organisations such as credit unions and agricultural cooperatives, emphasising member benefit and democratic control. They can raise member share capital and borrowing. Non-profit clubs and societies organise services rather than distributing business profits to owners. Distinguish share capital, reserves, retained earnings, member funds and liabilities instead of labelling every source of money as profit."]},{"title":"Worked example","paragraphs":["A company issues $100,000 of ordinary shares and borrows $40,000 by debentures. Bank increases $140,000; share capital increases $100,000; debenture liability increases $40,000. A 6% debenture carries annual interest $2,400 under the stated terms, regardless of whether an ordinary dividend is declared."]},{"title":"Common mistake","paragraphs":["Limited liability does not mean the company itself has no debts or can ignore creditors."]}],"keyPoints":["No. It raises borrowed funds and creates a liability.","Limited liability does not mean the company itself has no debts or can ignore creditors."],"summary":"Check your understanding: Does a debenture issue increase share capital?","check":{"question":"Does a debenture issue increase share capital?","answer":"No. It raises borrowed funds and creates a liability."},"flashcards":[{"front":"Does a debenture issue increase share capital?","back":"No. It raises borrowed funds and creates a liability."},{"front":"What mistake should you avoid when studying companies, cooperatives and member organisations?","back":"Limited liability does not mean the company itself has no debts or can ignore creditors."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s9-lesson-25','poa-section-9','Share issues, dividends and final accounts','On a cash issue at nominal value, debit bank and credit the relevant share capital. If a premium is specified, split the proceeds between nominal share capital and share premium. Record a cash debenture issue by debiting bank and crediting debentures. Follow the question''s issue terms; do not invent a premium or treat share proceeds as sales revenue.',24,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":25,"section":9,"objectiveCodes":["S9.6","S9.7","S9.8","S9.9","S9.10"]},"lesson":{"introduction":"On a cash issue at nominal value, debit bank and credit the relevant share capital. If a premium is specified, split the proceeds between nominal share capital and share premium. Record a cash debenture issue by debiting bank and crediting debentures. Follow the question''s issue terms; do not invent a premium or treat share proceeds as sales revenue.","objectives":["prepare journal entries to record the issue of shares and debentures","calculate dividend payments for various types of shares","appropriate profits between dividends and reserves;","prepare the final accounts of limited liability companies and co-operatives","analyse performance and position using ratios"],"sections":[{"title":"Understand the idea","paragraphs":["A percentage preference dividend is normally calculated on the stated nominal preference capital, not on profit or market value. An ordinary dividend may be given per share or as a percentage of nominal capital; identify the base carefully. Appropriation allocates available profit between dividends, reserves and retained earnings. Debenture interest is an expense before profit appropriation. A transfer to reserve reallocates equity; it is not an operating cost or a separate cash payment.","Prepare the income statement with the appropriate expenses, then the distribution or appropriation and the balance sheet. Equity contains share capital and reserves/retained earnings; loans and debentures are liabilities. For a cooperative, show the surplus and its distribution using the given rules. Apply profitability and liquidity ratios using the correct organisation''s capital and stated definitions, then explain what the numbers imply."]},{"title":"Worked example","paragraphs":["Preference capital $40,000 at 5% gives dividend $2,000. Ordinary capital comprises 30,000 $1 shares; a dividend of $0.10 each is $3,000. Profit available $12,000 less preference dividend $2,000, ordinary dividend $3,000 and reserve transfer $1,500 leaves $5,500 retained for the period. Opening retained earnings must be added if the question asks for the closing balance."]},{"title":"Common mistake","paragraphs":["Do not deduct dividends when calculating gross profit or operating profit."]}],"keyPoints":["10,000 × $2 × 6% = $1,200.","Do not deduct dividends when calculating gross profit or operating profit."],"summary":"Check your understanding: 10,000 shares of $2 nominal value receive a 6% dividend. Total dividend?","check":{"question":"10,000 shares of $2 nominal value receive a 6% dividend. Total dividend?","answer":"10,000 × $2 × 6% = $1,200."},"flashcards":[{"front":"10,000 shares of $2 nominal value receive a 6% dividend. Total dividend?","back":"10,000 × $2 × 6% = $1,200."},{"front":"What mistake should you avoid when studying share issues, dividends and final accounts?","back":"Do not deduct dividends when calculating gross profit or operating profit."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s9-lesson-26','poa-section-9','Receipts and payments for clubs','A receipts and payments account summarises actual money received and paid by a non-profit organisation over a period. Begin with opening cash and bank balances, add all receipts and deduct all payments to find closing cash and bank. Include capital and revenue cash movements, even if they relate to another accounting period.',25,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":26,"section":9,"objectiveCodes":["S9.11"]},"lesson":{"introduction":"A receipts and payments account summarises actual money received and paid by a non-profit organisation over a period. Begin with opening cash and bank balances, add all receipts and deduct all payments to find closing cash and bank. Include capital and revenue cash movements, even if they relate to another accounting period.","objectives":["prepare receipts and payment accounts for non-profit organisations"],"sections":[{"title":"Understand the idea","paragraphs":["Typical receipts include subscriptions, donations, event takings and proceeds from selling equipment. Payments include rent, utilities, equipment purchases and event costs. A depreciation charge does not appear because no money is paid when depreciation is recorded. An unpaid bill and subscriptions owing also do not appear until cash moves. Keep a supporting schedule so the source of each total can be traced.","An income and expenditure account is different: it adjusts revenue and expenses for the period and reports surplus or deficit. The current syllabus requires preparation of the receipts and payments account here, while learners should still recognise the purpose of income and expenditure. Never describe a closing cash balance as the club''s surplus without checking accruals and capital transactions."]},{"title":"Worked example","paragraphs":["A youth club opens with bank $3,000, collects subscriptions $9,000 and donations $2,000, pays equipment $4,500 and expenses $5,000. Closing bank = 3,000 + 9,000 + 2,000 − 4,500 − 5,000 = $4,500. The equipment payment is included in full; depreciation is excluded."]},{"title":"Common mistake","paragraphs":["Opening cash is a balance brought forward, not income earned this year."]}],"keyPoints":["No. Record the payment when it occurs; the unpaid expense matters to accrual accounts, not this cash summary.","Opening cash is a balance brought forward, not income earned this year."],"summary":"Check your understanding: A club owes $600 for electricity at year end. Does the unpaid amount enter receipts and payments?","check":{"question":"A club owes $600 for electricity at year end. Does the unpaid amount enter receipts and payments?","answer":"No. Record the payment when it occurs; the unpaid expense matters to accrual accounts, not this cash summary."},"flashcards":[{"front":"A club owes $600 for electricity at year end. Does the unpaid amount enter receipts and payments?","back":"No. Record the payment when it occurs; the unpaid expense matters to accrual accounts, not this cash summary."},{"front":"What mistake should you avoid when studying receipts and payments for clubs?","back":"Opening cash is a balance brought forward, not income earned this year."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s10-lesson-27','poa-section-10','Manufacturing accounts and unit cost','A manufacturer converts raw materials into finished goods. Direct materials can be traced to a product, such as flour in bread. Direct labour works on the product. Other traceable direct expenses may also be included. Indirect factory costs, such as a supervisor''s salary, factory rent and machinery depreciation, are overheads. Office salaries and selling expenses are normally excluded from factory production cost.',26,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":27,"section":10,"objectiveCodes":["S10.1","S10.2","S10.3","S10.4"]},"lesson":{"introduction":"A manufacturer converts raw materials into finished goods. Direct materials can be traced to a product, such as flour in bread. Direct labour works on the product. Other traceable direct expenses may also be included. Indirect factory costs, such as a supervisor''s salary, factory rent and machinery depreciation, are overheads. Office salaries and selling expenses are normally excluded from factory production cost.","objectives":["distinguish between direct and indirect costs","prepare manufacturing accounts","calculate unit cost of items produced","prepare final accounts for a manufacturing concern"],"sections":[{"title":"Understand the idea","paragraphs":["Raw materials consumed = opening raw materials + net raw material purchases + relevant carriage − closing raw materials. Prime cost = direct materials consumed + direct labour + direct expenses. Add factory overheads, add opening work in progress and deduct closing work in progress to find cost of production. Work in progress is partly completed production; closing work not yet finished must remain an asset rather than all being charged to completed goods.","Unit production cost = cost of completed production ÷ completed units. Transfer cost of production to the trading section. Cost of finished goods sold = opening finished goods + cost of production − closing finished goods, adjusted for any other stated items. Show raw materials, work in progress and finished goods separately as appropriate in the balance sheet. Production cost is not automatically the selling price."]},{"title":"Worked example","paragraphs":["Opening raw materials $5,000 + purchases $28,000 + carriage $2,000 − closing $6,000 = materials consumed $29,000. Add direct wages $20,000: prime cost $49,000. Add factory overhead $11,000, opening WIP $4,000, less closing WIP $7,000: production cost $57,000. For 3,000 completed units, unit cost is $19."]},{"title":"Common mistake","paragraphs":["Closing work in progress is deducted; opening work in progress is added. Do not reverse them."]}],"keyPoints":["Factory overhead, because it supports production.","Closing work in progress is deducted; opening work in progress is added. Do not reverse them."],"summary":"Check your understanding: Where does factory-machine depreciation go: factory overhead or selling expense?","check":{"question":"Where does factory-machine depreciation go: factory overhead or selling expense?","answer":"Factory overhead, because it supports production."},"flashcards":[{"front":"Where does factory-machine depreciation go: factory overhead or selling expense?","back":"Factory overhead, because it supports production."},{"front":"What mistake should you avoid when studying manufacturing accounts and unit cost?","back":"Closing work in progress is deducted; opening work in progress is added. Do not reverse them."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s10-lesson-28','poa-section-10','Costing and setting prices','Cost-plus pricing adds an intended profit amount to a relevant cost. A mark-up of r% on cost gives selling price = cost × (1 + r/100). A profit margin of m% of selling price instead gives selling price = cost ÷ (1 − m/100). Identify the denominator; the same numeric percentage produces different prices under these two methods.',27,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":27,"section":10,"objectiveCodes":["S10.5"]},"lesson":{"introduction":"Cost-plus pricing adds an intended profit amount to a relevant cost. A mark-up of r% on cost gives selling price = cost × (1 + r/100). A profit margin of m% of selling price instead gives selling price = cost ÷ (1 − m/100). Identify the denominator; the same numeric percentage produces different prices under these two methods.","objectives":["apply basic costing principles"],"sections":[{"title":"Understand the idea","paragraphs":["Absorption costing includes an appropriate share of production overhead in product cost, alongside direct costs. If overhead is allocated by labour hours, overhead rate = budgeted factory overhead ÷ budgeted labour hours. Multiply the rate by the hours used by each product. Choose the base given in the question rather than automatically dividing by units where products use resources differently.","A price should cover the intended costs, but customers, competitors, waste, capacity and demand also matter. Distinguish factory production cost from full business cost: office and selling costs still have to be covered by overall revenue. Explain the basis of a recommendation and show the cost calculations, rather than claiming any cost-plus price guarantees a profit."]},{"title":"Worked example","paragraphs":["Factory overhead $24,000 ÷ 6,000 labour hours = $4 per hour. A product needs materials $12, direct labour $8 and two labour hours of overhead $8: absorbed production cost $28. A 25% mark-up gives $35. A 25% margin would require $28/0.75 = $37.33 approximately."]},{"title":"Common mistake","paragraphs":["Do not include the same overhead once in a unit cost and again as an additional markup cost."]}],"keyPoints":["$80/(1 − 0.20) = $100; profit $20 is 20% of selling price.","Do not include the same overhead once in a unit cost and again as an additional markup cost."],"summary":"Check your understanding: Cost is $80 and desired margin is 20%. Selling price?","check":{"question":"Cost is $80 and desired margin is 20%. Selling price?","answer":"$80/(1 − 0.20) = $100; profit $20 is 20% of selling price."},"flashcards":[{"front":"Cost is $80 and desired margin is 20%. Selling price?","back":"$80/(1 − 0.20) = $100; profit $20 is 20% of selling price."},{"front":"What mistake should you avoid when studying costing and setting prices?","back":"Do not include the same overhead once in a unit cost and again as an additional markup cost."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s10-lesson-29','poa-section-10','FIFO, LIFO and average inventory cost','Inventory valuation assigns costs to goods issued and goods remaining. FIFO, first in first out, issues the oldest cost layers first. LIFO, last in first out, issues the newest layers first. Average cost uses a weighted cost per unit; check whether the question requires periodic weighted average or moving average after each receipt. These are cost-flow assumptions and do not necessarily describe the physical movement of goods.',28,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":27,"section":10,"objectiveCodes":["S10.6","S10.7"]},"lesson":{"introduction":"Inventory valuation assigns costs to goods issued and goods remaining. FIFO, first in first out, issues the oldest cost layers first. LIFO, last in first out, issues the newest layers first. Average cost uses a weighted cost per unit; check whether the question requires periodic weighted average or moving average after each receipt. These are cost-flow assumptions and do not necessarily describe the physical movement of goods.","objectives":["list methods of inventory valuation","calculate the value of closing inventory using either FIFO or LIFO; AVCO."],"sections":[{"title":"Understand the idea","paragraphs":["Keep a stock record with date, receipts, issues and balance. Under FIFO or LIFO retain quantities and unit costs in separate layers. Do not sell or issue more units than are available at that date. Moving average cost = value available after a receipt ÷ quantity available after that receipt; subsequent issues use that rate until another receipt. Keep enough precision during calculations and round final money consistently.","When purchase prices rise, FIFO usually leaves newer, higher-cost closing stock and gives lower cost of sales and higher profit than LIFO for the same transactions. Weighted average normally lies between them. The syllabus includes LIFO for learning and examination calculations; this does not imply it is permitted by every financial reporting framework. Closing inventory must also be assessed under the valuation instructions given."]},{"title":"Worked example","paragraphs":["Buy 10 units at $5 and 10 at $7, then issue 12. FIFO issue cost = 10×5 + 2×7 = $64; remaining 8×7 = $56. LIFO issue cost = 10×7 + 2×5 = $80; remaining 8×5 = $40. Weighted average = $120/20 = $6; issue $72 and closing $48. Total issue cost plus closing value is always $120 here."]},{"title":"Common mistake","paragraphs":["A simple average of prices is wrong when quantities differ. Weight each price by its quantity."]}],"keyPoints":["(5×4 + 15×8)/20 = $7 per unit.","A simple average of prices is wrong when quantities differ. Weight each price by its quantity."],"summary":"Check your understanding: Buy 5 units at $4 and 15 at $8. Weighted average cost?","check":{"question":"Buy 5 units at $4 and 15 at $8. Weighted average cost?","answer":"(5×4 + 15×8)/20 = $7 per unit."},"flashcards":[{"front":"Buy 5 units at $4 and 15 at $8. Weighted average cost?","back":"(5×4 + 15×8)/20 = $7 per unit."},{"front":"What mistake should you avoid when studying fifo, lifo and average inventory cost?","back":"A simple average of prices is wrong when quantities differ. Weight each price by its quantity."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s11-lesson-30','poa-section-11','Payments and payroll evidence','Businesses pay employees, suppliers and service providers by cash, cheque, transfer, standing order, direct debit and point-of-sale methods. A standing order is normally an instruction to pay a set amount regularly; a direct debit authorises the recipient to collect under agreed terms. Choose a method that suits security, timing, records and the recipient''s access. Keep authorisation and proof of payment.',29,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":29,"section":11,"objectiveCodes":["S11.1","S11.2","S11.4","S11.5"]},"lesson":{"introduction":"Businesses pay employees, suppliers and service providers by cash, cheque, transfer, standing order, direct debit and point-of-sale methods. A standing order is normally an instruction to pay a set amount regularly; a direct debit authorises the recipient to collect under agreed terms. Choose a method that suits security, timing, records and the recipient''s access. Keep authorisation and proof of payment.","objectives":["list methods of payment","identify basic source documents of the payroll","identify main accounting software used for payroll","distinguish between voluntary and statutory deductions"],"sections":[{"title":"Understand the idea","paragraphs":["Payroll starts with employee records, agreed rates, time cards, time books or electronic attendance. Check ordinary hours, overtime, leave and approved deductions. Payroll software and spreadsheets can calculate earnings, deductions and reports, but records must be checked for incorrect rates, duplicated employees and unauthorised changes. Separate preparation, authorisation and payment where possible.","Statutory deductions are required under applicable law, such as income tax or social security. Voluntary deductions are authorised by the employee, such as a savings contribution or loan repayment. Rates and thresholds vary by territory and date; an exercise should supply them or use verified current rules. In this course''s calculators, entered deductions are exercise values and are not asserted to be current legal tax calculations."]},{"title":"Worked example","paragraphs":["A time record shows 40 ordinary hours and 5 approved overtime hours. Before calculating pay, confirm the rate, overtime multiplier and which deductions apply. A missing approval is a control problem even if the arithmetic is correct."]},{"title":"Common mistake","paragraphs":["Do not copy a statutory deduction rate from another country or an old past paper into a current real payroll."]}],"keyPoints":["Voluntary. It follows the employee''s authorisation rather than an automatic legal requirement.","Do not copy a statutory deduction rate from another country or an old past paper into a current real payroll."],"summary":"Check your understanding: Is an employee''s authorised savings-club deduction statutory or voluntary?","check":{"question":"Is an employee''s authorised savings-club deduction statutory or voluntary?","answer":"Voluntary. It follows the employee''s authorisation rather than an automatic legal requirement."},"flashcards":[{"front":"Is an employee''s authorised savings-club deduction statutory or voluntary?","back":"Voluntary. It follows the employee''s authorisation rather than an automatic legal requirement."},{"front":"What mistake should you avoid when studying payments and payroll evidence?","back":"Do not copy a statutory deduction rate from another country or an old past paper into a current real payroll."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s11-lesson-31','poa-section-11','Calculate gross pay, deductions and net pay','Gross pay is earnings before deductions. Time-rate ordinary pay = ordinary hours × hourly rate. Overtime pay = overtime hours × hourly rate × overtime multiplier. Add any stated bonus, commission or piecework earnings. Piecework pay uses units produced × rate per unit. If salary is given for a month, do not multiply it by hours unless the question requires a conversion.',30,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":29,"section":11,"objectiveCodes":["S11.3","S11.6"]},"lesson":{"introduction":"Gross pay is earnings before deductions. Time-rate ordinary pay = ordinary hours × hourly rate. Overtime pay = overtime hours × hourly rate × overtime multiplier. Add any stated bonus, commission or piecework earnings. Piecework pay uses units produced × rate per unit. If salary is given for a month, do not multiply it by hours unless the question requires a conversion.","objectives":["prepare spreadsheet to arrive at net pay amounts after deductions","calculate employees’ earnings"],"sections":[{"title":"Understand the idea","paragraphs":["Net pay = gross pay − total employee deductions. Calculate each deduction on its stated base: some may use gross earnings, a taxable amount after allowances, or a fixed sum. Employer contributions are a separate employer cost unless the question explicitly includes them in employee deductions. They should not automatically reduce net pay.","In a payroll spreadsheet, give each input a clear column, use formulas for ordinary pay, overtime, gross, deductions and net, and total the columns. Validate non-negative hours and sensible rates. Keep employee identifiers and a pay-period date. Check that gross minus employee deductions equals net for each person and for the payroll total. Review unusual values before payment; a formula copied into the wrong row can still produce a plausible number."]},{"title":"Worked example","paragraphs":["Ordinary 40 hours at $500 = $20,000. Overtime 6 hours at time-and-a-half = 6×500×1.5 = $4,500. Bonus $1,000 gives gross $25,500. Exercise deductions: 5% of gross $1,275, fixed $2,000 and savings $500. Total deductions $3,775; net pay $21,725. These are illustrative exercise deductions, not a statement of current statutory rates."]},{"title":"Common mistake","paragraphs":["Overtime at time-and-a-half is 1.5 times the ordinary rate, not the ordinary rate plus another 1.5 times."]}],"keyPoints":["$25,200.","Overtime at time-and-a-half is 1.5 times the ordinary rate, not the ordinary rate plus another 1.5 times."],"summary":"Check your understanding: Gross pay $30,000 less deductions $4,800. Net pay?","check":{"question":"Gross pay $30,000 less deductions $4,800. Net pay?","answer":"$25,200."},"flashcards":[{"front":"Gross pay $30,000 less deductions $4,800. Net pay?","back":"$25,200."},{"front":"What mistake should you avoid when studying calculate gross pay, deductions and net pay?","back":"Overtime at time-and-a-half is 1.5 times the ordinary rate, not the ordinary rate plus another 1.5 times."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s11-lesson-32','poa-section-11','Six-month cash flow forecasts','A cash flow projection estimates when cash will enter and leave the business. It helps an entrepreneur identify shortfalls early. For each month, opening cash + cash inflows − cash outflows = closing cash. The next month''s opening equals the previous month''s closing. Include owner investment, loans and grants as inflows when actually received, and asset purchases or loan principal as outflows when paid.',31,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":29,"section":11,"objectiveCodes":["S11.7"]},"lesson":{"introduction":"A cash flow projection estimates when cash will enter and leave the business. It helps an entrepreneur identify shortfalls early. For each month, opening cash + cash inflows − cash outflows = closing cash. The next month''s opening equals the previous month''s closing. Include owner investment, loans and grants as inflows when actually received, and asset purchases or loan principal as outflows when paid.","objectives":["prepare cash flow projections within a six-month period;"],"sections":[{"title":"Understand the idea","paragraphs":["Separate cash sales from credit collections. If customers pay a month after sale, January credit sales become February collections under that assumption. Likewise a purchase made on credit is paid in the month specified by supplier terms. Depreciation is not a cash payment. Profit is not an additional inflow to add on top of sales receipts: that would count the same activity twice.","Lay out six monthly columns with receipts, payments, net flow, opening and closing cash. Use realistic timing and state assumptions about demand, late payments and costs. A negative closing balance indicates a financing need or a need to change timing; it is not automatically permission to overdraw. Explore earlier collection, delayed non-essential spending or suitable finance, and assess the cost and feasibility of each."]},{"title":"Worked example","paragraphs":["January opens $5,000, receives $12,000 and pays $14,000: closing $3,000. February opens $3,000, receives $10,000 and pays $15,000: closing −$2,000. The business must address the projected $2,000 shortfall before payments fall due. A new $4,000 loan received in February would make its closing cash $2,000 but also create a debt."]},{"title":"Common mistake","paragraphs":["Do not restart every month with the original opening cash balance."]}],"keyPoints":["No. The equipment payment is a cash movement; depreciation allocates cost without a new cash payment.","Do not restart every month with the original opening cash balance."],"summary":"Check your understanding: Is depreciation included as a cash outflow?","check":{"question":"Is depreciation included as a cash outflow?","answer":"No. The equipment payment is a cash movement; depreciation allocates cost without a new cash payment."},"flashcards":[{"front":"Is depreciation included as a cash outflow?","back":"No. The equipment payment is a cash movement; depreciation allocates cost without a new cash payment."},{"front":"What mistake should you avoid when studying six-month cash flow forecasts?","back":"Do not restart every month with the original opening cash balance."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata) values ('principles-of-accounts','poa-s11-lesson-33','poa-section-11','Sales budgets, production budgets and a business plan','A sales budget estimates units sold and sales value. Sales value = budgeted units × selling price. A production budget links sales demand to stock targets: production units = sales units + desired closing finished goods − opening finished goods. The closing inventory of one month becomes the next month''s opening inventory. Production is not always equal to sales.',32,true,'{"syllabus":{"source":"CXC 10/G/SYLL 17","sourcePage":30,"section":11,"objectiveCodes":["S11.8","S11.9"]},"lesson":{"introduction":"A sales budget estimates units sold and sales value. Sales value = budgeted units × selling price. A production budget links sales demand to stock targets: production units = sales units + desired closing finished goods − opening finished goods. The closing inventory of one month becomes the next month''s opening inventory. Production is not always equal to sales.","objectives":["prepare sales and production budgets for a three-month period","use accounting knowledge and skills to prepare a simple business plan"],"sections":[{"title":"Understand the idea","paragraphs":["For a three-month plan, calculate quantities first, then materials, labour and overhead needs. Materials needed = production × material per unit; adjust for opening and desired closing raw materials to find purchases. State assumptions about selling prices, unit costs, demand and capacity. Budgeted sales revenue and cash collections differ where customers buy on credit.","A simple business plan explains the product or service, customers, evidence of demand, competitors, operations, staffing, startup assets, finance, budgets, cash forecasts and risks. For a poultry or craft project, connect quantities and costs to realistic capacity. Show how records will be kept and how performance will be checked against budgets. A sensible plan explains what happens if sales are lower or input costs rise rather than promising guaranteed returns."]},{"title":"Worked example","paragraphs":["January sales target 200 units at $150 gives revenue $30,000. Opening finished goods 30 units and desired closing 50 require production 200 + 50 − 30 = 220 units. If each uses 2 kg of material, production needs 440 kg. With opening raw materials 40 kg and desired closing 60 kg, buy 440 + 60 − 40 = 460 kg."]},{"title":"Common mistake","paragraphs":["A production budget counts units to make; a cash budget counts money expected to move. Do not mix the columns."]}],"keyPoints":["500 + 100 − 80 = 520 units.","A production budget counts units to make; a cash budget counts money expected to move. Do not mix the columns."],"summary":"Check your understanding: Sales budget 500 units, opening inventory 80, target closing 100. Production required?","check":{"question":"Sales budget 500 units, opening inventory 80, target closing 100. Production required?","answer":"500 + 100 − 80 = 520 units."},"flashcards":[{"front":"Sales budget 500 units, opening inventory 80, target closing 100. Production required?","back":"500 + 100 − 80 = 520 units."},{"front":"What mistake should you avoid when studying sales budgets, production budgets and a business plan?","back":"A production budget counts units to make; a cash budget counts money expected to move. Do not mix the columns."}]}}'::jsonb) on conflict(subject_id,topic_id) do update set title=excluded.title,description=excluded.description,section_id=excluded.section_id,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
